-- CARDIOSYNC V1 - Execute integralmente no SQL Editor do Supabase
create extension if not exists pgcrypto;
create table if not exists profissionais(id uuid primary key default gen_random_uuid(),nome text not null unique,tipo text,ativo boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists pagadores(id uuid primary key default gen_random_uuid(),nome text not null unique,ativo boolean not null default true,created_at timestamptz not null default now());
create table if not exists procedimentos(id uuid primary key default gen_random_uuid(),codigo text not null unique,descricao text not null,tabela text not null default '22',inicio_vigencia date,fim_vigencia date,ativo boolean not null default true,created_at timestamptz not null default now());
create table if not exists importacoes_xml(id uuid primary key default gen_random_uuid(),nome_arquivo text not null,hash_arquivo text,competencia date,total_atendimentos integer not null default 0,valor_total numeric(14,2) not null default 0,imported_at timestamptz not null default now(),unique(hash_arquivo));
create table if not exists atendimentos(id uuid primary key default gen_random_uuid(),importacao_id uuid references importacoes_xml(id) on delete set null,guia text,paciente text,data_atendimento date not null,pagador_id uuid references pagadores(id),procedimento_id uuid references procedimentos(id),valor_faturado numeric(14,2) not null check(valor_faturado>=0),prazo_dias integer check(prazo_dias is null or prazo_dias>=0),status_financeiro text not null default 'ABERTO' check(status_financeiro in ('ABERTO','PARCIAL','RECEBIDO','GLOSADO','ATRASADO','PERDIDO')),created_at timestamptz not null default now());
create table if not exists atendimento_participantes(id uuid primary key default gen_random_uuid(),atendimento_id uuid not null references atendimentos(id) on delete cascade,profissional_id uuid not null references profissionais(id),grau_participacao text not null,nome_xml text,created_at timestamptz not null default now(),unique(atendimento_id,profissional_id,grau_participacao));
create table if not exists regras_repasse(id uuid primary key default gen_random_uuid(),nome text not null,codigo_procedimento text,vigencia_inicio date not null,vigencia_fim date,ativo boolean not null default true,observacao text,created_at timestamptz not null default now(),check(vigencia_fim is null or vigencia_fim>=vigencia_inicio));
create table if not exists regras_participantes(id uuid primary key default gen_random_uuid(),regra_id uuid not null references regras_repasse(id) on delete cascade,profissional_id uuid not null references profissionais(id),condicao text not null default 'PRESENTE' check(condicao in ('PRESENTE','AUSENTE','INDIFERENTE')),papel text,unique(regra_id,profissional_id));
create table if not exists regras_rateio(id uuid primary key default gen_random_uuid(),regra_id uuid not null references regras_repasse(id) on delete cascade,destinatario_tipo text not null check(destinatario_tipo in ('PROFISSIONAL','CLINICA','PAPEL')),profissional_id uuid references profissionais(id),papel text,tipo_calculo text not null default 'PERCENTUAL' check(tipo_calculo in ('PERCENTUAL','VALOR_FIXO')),valor numeric(14,4) not null check(valor>=0),check((destinatario_tipo='PROFISSIONAL' and profissional_id is not null) or destinatario_tipo<>'PROFISSIONAL'));
create table if not exists repasses_calculados(id uuid primary key default gen_random_uuid(),atendimento_id uuid not null references atendimentos(id) on delete restrict,regra_id uuid references regras_repasse(id) on delete restrict,profissional_id uuid references profissionais(id),destinatario text not null,percentual_aplicado numeric(8,4),valor_repasse numeric(14,2) not null check(valor_repasse>=0),competencia date not null,calculado_em timestamptz not null default now(),fechado boolean not null default false,unique(atendimento_id,destinatario,profissional_id));
create table if not exists recebimentos(id uuid primary key default gen_random_uuid(),pagador_id uuid references pagadores(id),data_recebimento date not null,valor_recebido numeric(14,2) not null check(valor_recebido>0),referencia text,observacao text,created_at timestamptz not null default now());
create table if not exists recebimento_itens(id uuid primary key default gen_random_uuid(),recebimento_id uuid not null references recebimentos(id) on delete cascade,atendimento_id uuid not null references atendimentos(id) on delete restrict,valor_baixado numeric(14,2) not null check(valor_baixado>0),unique(recebimento_id,atendimento_id));
create index if not exists idx_atendimentos_data on atendimentos(data_atendimento);create index if not exists idx_atendimentos_status on atendimentos(status_financeiro);create index if not exists idx_participantes_atendimento on atendimento_participantes(atendimento_id);create index if not exists idx_repasses_competencia on repasses_calculados(competencia);create index if not exists idx_regras_vigencia on regras_repasse(codigo_procedimento,vigencia_inicio,vigencia_fim);
create or replace view vw_atendimentos_financeiro as select a.*,coalesce(sum(ri.valor_baixado),0)::numeric(14,2) valor_recebido,(a.valor_faturado-coalesce(sum(ri.valor_baixado),0))::numeric(14,2) saldo,case when coalesce(sum(ri.valor_baixado),0)>=a.valor_faturado then 'RECEBIDO' when coalesce(sum(ri.valor_baixado),0)>0 then 'PARCIAL' when current_date>a.data_atendimento+coalesce(a.prazo_dias,90) then 'ATRASADO' else a.status_financeiro end status_calculado,(current_date-a.data_atendimento) dias_decorridos from atendimentos a left join recebimento_itens ri on ri.atendimento_id=a.id group by a.id;
insert into pagadores(nome) values('Hospital'),('Particular') on conflict(nome) do nothing;
insert into profissionais(nome,tipo) values('Felipe','Principal'),('Juan','Principal'),('Rayza','Auxiliar'),('Mariel','Auxiliar'),('Elton','Auxiliar') on conflict(nome) do nothing;
insert into regras_repasse(nome,vigencia_inicio,observacao) select x.nome,date '2026-01-01','Regra inicial derivada da planilha de repasses.' from (values('Equipe completa'),('Sem Elton'),('Sem Mariel'),('Sem Rayza'),('Sem Rayza e Mariel'),('Sem Mariel e Elton'),('Sem Rayza e Elton'),('Felipe + Juan')) x(nome) where not exists(select 1 from regras_repasse r where r.nome=x.nome and r.vigencia_inicio=date '2026-01-01');
-- Segurança: somente usuários autenticados acessam as tabelas.
do $$ declare t text; begin foreach t in array array['profissionais','pagadores','procedimentos','importacoes_xml','atendimentos','atendimento_participantes','regras_repasse','regras_participantes','regras_rateio','repasses_calculados','recebimentos','recebimento_itens'] loop execute format('alter table %I enable row level security',t); execute format('drop policy if exists authenticated_all on %I',t); execute format('create policy authenticated_all on %I for all to authenticated using (true) with check (true)',t); end loop; end $$;
grant select,insert,update,delete on all tables in schema public to authenticated;grant select on vw_atendimentos_financeiro to authenticated;
